<?php
class ProfesorModel {private PDO $pdo;function __construct(PDO $pdo){$this->pdo=$pdo;} function obtenerTodas(){return $this->pdo->query("SELECT p.*,u.nombre,u.apellido,u.correo,u.usuario FROM profesores p JOIN usuarios u ON u.id_usuario=p.id_usuario ORDER BY u.apellido,u.nombre")->fetchAll();} function obtenerPorId($id){$s=$this->pdo->prepare('SELECT p.*,u.nombre,u.apellido,u.correo,u.usuario,u.telefono FROM profesores p JOIN usuarios u ON u.id_usuario=p.id_usuario WHERE p.id_profesor=?');$s->execute([$id]);return $s->fetch();} function obtenerPorUsuario($id){$s=$this->pdo->prepare('SELECT p.* FROM profesores p WHERE p.id_usuario=?');$s->execute([$id]);return $s->fetch();}
 function crear($d){$this->pdo->beginTransaction();try{$u=$this->pdo->prepare('INSERT INTO usuarios(id_rol,nombre,apellido,correo,usuario,contrasena_hash,telefono) VALUES(2,?,?,?,?,?,?)');$u->execute([$d['nombre'],$d['apellido'],$d['correo'],$d['usuario'],password_hash($d['clave'],PASSWORD_DEFAULT),$d['telefono']??null]);$uid=$this->pdo->lastInsertId();$s=$this->pdo->prepare('INSERT INTO profesores(id_usuario,especialidad,biografia) VALUES(?,?,?)');$s->execute([$uid,$d['especialidad'],$d['biografia']]);$pid=$this->pdo->lastInsertId();$t=$this->pdo->prepare('INSERT INTO tutores(id_profesor,especialidad,biografia) VALUES(?,?,?)');$t->execute([$pid,$d['especialidad'],$d['biografia']]);$this->pdo->commit();return true;}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
 function editar($id,$d){$row=$this->obtenerPorId($id);$this->pdo->beginTransaction();try{$u=$this->pdo->prepare('UPDATE usuarios SET nombre=?,apellido=?,correo=?,usuario=?,telefono=? WHERE id_usuario=?');$u->execute([$d['nombre'],$d['apellido'],$d['correo'],$d['usuario'],$d['telefono']??null,$row['id_usuario']]);$s=$this->pdo->prepare('UPDATE profesores SET especialidad=?,biografia=? WHERE id_profesor=?');$s->execute([$d['especialidad'],$d['biografia'],$id]);$t=$this->pdo->prepare('UPDATE tutores SET especialidad=?,biografia=? WHERE id_profesor=?');$t->execute([$d['especialidad'],$d['biografia'],$id]);$this->pdo->commit();return true;}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
 function eliminar($id){$s=$this->pdo->prepare('SELECT id_usuario FROM profesores WHERE id_profesor=?');$s->execute([$id]);$u=$s->fetchColumn();if(!$u)return false;$s=$this->pdo->prepare('DELETE FROM usuarios WHERE id_usuario=?');return $s->execute([$u]);}}
